import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
import net.neoforged.neoforge.network.configuration.ConfigurationProtocol;
import net.neoforged.neoforge.network.play.PlayProtocol;

NeoForge.EVENT_BUS.addListener((RegisterPayloadHandlersEvent event) -> {
    event.register(PlayProtocol.class, payloadRegistry -> {
        payloadRegistry.register(
            MyPayload.ID,
            MyPayload::new,
            (payload, context) -> payload.handle(context)
        );
    });
});
